action.mutation:
mutation CreateProcess($payload: [ProcessCreatePayloadInput!]!) {
  mutation: createProcess(payload: $payload) {
    id
    code
  }
}

mutation UpdateProcess($payload: [ProcessUpdatePayloadInput!]!) {
  mutation: updateProcess(payload: $payload) {
    id
    code
  }
}

mutation DeleteProcess($payload: [ProcessDeletePayloadInput!]!) {
  mutation: deleteProcess(payload: $payload) { 
    id
    code
  }
}

mutation CreateProductCategory($payload: [ProductCategoryCreatePayloadInput!]!) {
  mutation: createProductCategory(payload: $payload) {
    id
    name
  }
}

mutation UpdateProductCategory($payload: [ProductCategoryUpdatePayloadInput!]!) {
  mutation: updateProductCategory(payload: $payload) {
    id
    name
  }
}

mutation DeleteProductCategory($payload: [ProductCategoryDeletePayloadInput!]!) {
  mutation: deleteProductCategory(payload: $payload) { 
    id
    name
  }
}
